-- | Tests for declared input sources (candidate Language 6
-- @input <Name> from intake <Intake> event <Event>+ …@): parsing, printing,
-- predecessor refusal, the two checker diagnostics, and the proof that a
-- declared source changes no generated byte, fingerprint, ledger or diff.
module Keiro.Dsl.InputSourceSpec (inputSourceSpec) where

import Control.Exception (bracket)
import Control.Monad (filterM, forM, forM_)
import Data.ByteString qualified as BS
import Data.List (sort)
import Data.List.NonEmpty (NonEmpty (..))
import Data.List.NonEmpty qualified as NE
import Data.Text (Text)
import Data.Text qualified as T
import Data.Text.Encoding qualified as TE
import Keiro.Dsl.Diff (Change (..), diffSources)
import Keiro.Dsl.FoldFingerprint (aggregateFoldFingerprintForService)
import Keiro.Dsl.Grammar (InputDecl (..), InputSource (..), Node (..), ProcessBody (..), ProcessNode (..), ReactionBody (..), RouterNode (..))
import Keiro.Dsl.Grammar qualified as G
import Keiro.Dsl.LanguageVersion (ParsedSource (..))
import Keiro.Dsl.Parser (parseSourceDocument, renderParseFailure)
import Keiro.Dsl.PrettyPrint (renderSource)
import Keiro.Dsl.ProcessReaction (checkProcessReaction, processReactionFingerprint)
import Keiro.Dsl.ReplayImpact (ReplayImpact (..), replayImpactServices)
import Keiro.Dsl.RouterSelection (checkRouterSelection, routerSelectionFingerprint)
import Keiro.Dsl.SemanticContract (CheckedService, checkedLanguageContract, checkedSource, checkedSpec)
import Keiro.Dsl.SourceIndex (ParsedSourceDocument (..))
import Keiro.Dsl.TypeGraph (resolveTypeGraph)
import Keiro.Dsl.Validate (Diagnostic (..), DiagnosticCode (..), Severity (..), validateService)
import Keiro.Dsl.Workspace (WorkspaceDiagnostic (..), checkWorkspace, fileContentSource, loadWorkspace)
import System.Directory (createDirectory, doesDirectoryExist, doesFileExist, getTemporaryDirectory, listDirectory, removeFile, removePathForcibly)
